  "recovered_c": "uint64_t custom_hash(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if ((0x17 < len) && (7 < out_cap)) {\n    uint32_t state1 = *in;\n    uint32_t state2 = in[1];\n    int i = 0;\n    do {\n      i = i + -0x61c88647;\n      state1 = state1 + (state2 * 0x10 + in[2] ^ (state2 >> 5) + in[3] ^ i + state2);\n      state2 = state2 + (state1 * 0x10 + in[4] ^ (state1 >> 5) + in[5] ^ i + state1);\n    } while (i != -0x3910c8e0);\n    out[0] = (state1 >> 0x18) & 0xff;\n    out[1] = (state1 >> 0x10) & 0xff;\n    out[2] = (state1 >> 8) & 0xff;\n    out[3] = state1 & 0xff;\n    out[4] = (state2 >> 0x18) & 0xff;\n    out[5] = (state2 >> 0x10) & 0xff;\n    out[6] = (state2 >> 8) & 0xff;\n    out[7] = state2 & 0xff;\n    return 8;\n  }\n  return 0xffffffffffffffff;\n}"
